1042	+/** A seeded pseudo-random fight that lasts the round: mostly movement and guard, with occasional one-frame attacks. */
1043	+function randomInputs(seed: number, frames: number): DuelInputs[] {
1044	+  let rng = seed;
1045	+  const draw = (bound: number) => {
1046	+    const drawn = nextInt(rng, bound);
1047	+    rng = drawn.state;
1048	+    return drawn.value;
1049	+  };
1050	+  const held = [0, 0];
1051	+  const left = [0, 0];
1052	+  const inputs: DuelInputs[] = [];
1053	+  for (let frame = 0; frame < frames; frame++) {
1054	+    for (const player of [0, 1] as const) {
1055	+      if (left[player] === 0) {
1056	+        // Player one starts on the left, so its back is left; player two's is right.
1057	+        const back = player === 0 ? I("left") : I("right");
1058	+        const forward = player === 0 ? I("right") : I("left");
1059	+        const moves = [0, back, back, back | I("down"), forward, forward, I("down"), I("up"), I("up") | forward, I("up") | back, I("dash"), back | I("dash"), I("left", "right")];
1060	+        const attacks = [I("light"), I("heavy"), I("down", "heavy"), forward | I("heavy"), I("down", "light"), I("special1"), I("special2"), I("light", "heavy")];
1061	+        const attack = draw(100) < 12;
1062	+        held[player] = attack ? attacks[draw(attacks.length)]! : moves[draw(moves.length)]!;
1063	+        left[player] = attack ? 1 : 1 + draw(30);
1064	+      }
1065	+      left[player]!--;
1066	+    }
1067	+    inputs.push([held[0]!, held[1]!]);
1068	+  }
1069	+  return inputs;
1070	+}
