1724	+import { DUEL_INPUT, DUEL_INPUT_MASK } from "@pirate-sea-race/content/moves";
1725	+
1726	+/** Player one's and player two's input bits (`DUEL_INPUT`) for one frame. */
1727	+export type DuelInputs = readonly [number, number];
1728	+
1729	+/** Anything that is not a non-negative safe integer becomes neutral; undefined bits are dropped. */
1730	+export function sanitizeDuelInput(bits: number): number {
1731	+  return Number.isSafeInteger(bits) && bits >= 0 ? bits & DUEL_INPUT_MASK : 0;
1732	+}
1733	+
1734	+/**
1735	+ * Held directions as axes: `h` is -1 (left), 0 or 1 (right); `v` is -1 (down), 0 or 1 (up). Both directions of an
1736	+ * axis held together are neutral (§8), whatever order the keys went down in.
1737	+ */
1738	+export function directions(bits: number): { h: -1 | 0 | 1; v: -1 | 0 | 1 } {
1739	+  const left = (bits & DUEL_INPUT.left) !== 0;
1740	+  const right = (bits & DUEL_INPUT.right) !== 0;
1741	+  const up = (bits & DUEL_INPUT.up) !== 0;
1742	+  const down = (bits & DUEL_INPUT.down) !== 0;
1743	+  return { h: left === right ? 0 : right ? 1 : -1, v: up === down ? 0 : up ? 1 : -1 };
1744	+}
1745	+
1746	+/** The same input for a fighter on the mirrored side of the arena: left and right swap. */
1747	+export function mirrorDuelInput(bits: number): number {
1748	+  const clean = sanitizeDuelInput(bits);
1749	+  const left = clean & DUEL_INPUT.left;
1750	+  const right = clean & DUEL_INPUT.right;
1751	+  return (clean & ~(DUEL_INPUT.left | DUEL_INPUT.right)) | (left !== 0 ? DUEL_INPUT.right : 0) | (right !== 0 ? DUEL_INPUT.left : 0);
1752	+}
1753	+
1754	+/** Input bits from button and direction names, for scripts and tests: `duelInput("down", "heavy")`. */
1755	+export function duelInput(...names: readonly (keyof typeof DUEL_INPUT)[]): number {
1756	+  return names.reduce((bits, name) => bits | DUEL_INPUT[name], 0);
1757	+}
