1774	+
1775	+/** Wraps recorded per-frame inputs, starting from a state at `startFrame`, in the input log format. */
1776	+export function createDuelInputLog(config: DuelConfig, startFrame: number, inputs: readonly DuelInputs[]): DuelInputLog {
1777	+  return {
1778	+    format: DUEL_INPUT_LOG_FORMAT,
1779	+    version: 1,
1780	+    movesetVersion: config.moveset.version,
1781	+    startFrame,
1782	+    inputs: inputs.map(([a, b]) => [a, b]),
