1785	+
1786	+/** The part of a log that replays from a state at `frame` (for a restored snapshot). */
1787	+export function sliceDuelInputLog(log: DuelInputLog, frame: number): DuelInputLog {
1788	+  if (!Number.isSafeInteger(frame) || frame < log.startFrame || frame > log.startFrame + log.inputs.length) {
1789	+    throw new RangeError(`frame ${frame} is outside the log (${log.startFrame} to ${log.startFrame + log.inputs.length})`);
1790	+  }
1791	+  return { ...log, startFrame: frame, inputs: log.inputs.slice(frame - log.startFrame) };
1792	+}
