1794	+/** Steps through per-frame inputs and returns every state, the initial one first (for scripted tests and tools). */
1795	+export function traceDuel(config: DuelConfig, initial: DuelState, inputs: readonly DuelInputs[]): DuelState[] {
1796	+  const states = [initial];
1797	+  for (const frameInputs of inputs) states.push(stepDuel(config, states[states.length - 1]!, frameInputs));
1798	+  return states;
