+import { DUEL_BUTTONS, DUEL_INPUT, type DuelMove, type DuelMoveset } from "@pirate-sea-race/content/moves";
+import { clampInt, divTrunc } from "../fixed.js";
+import { overlaps, worldBox, type Facing } from "./boxes.js";
+import { directions, sanitizeDuelInput, type DuelInputs } from "./input.js";
+import {
+  canAct,
+  findMove,
+  moveDuration,
+  type DuelConfig,
+  type DuelEvent,
+  type DuelResult,
+  type DuelState,
+  type FighterState,
+  type InputBuffer,
+  type PlayerIndex,
+  type Stance,
+} from "./state.js";
+
+/** One player's input for this frame, read against last frame's held buttons. */
+interface FrameInput {
+  readonly bits: number;
+  readonly h: -1 | 0 | 1;
+  readonly v: -1 | 0 | 1;
+  readonly buffer: InputBuffer;
+}
+
+/** What one fighter's move does to the other this frame, detected against the start-of-frame state. */
+interface Contact {
+  readonly kind: "hit" | "block" | "grab";
+  readonly move: DuelMove;
+  /** The defender's stance at contact. */
+  readonly stance: Stance;
+}
+
+type Pair<T> = readonly [T, T];
+
+const OTHER = [1, 0] as const;
+
+/**
+ * Advances the duel by one 60 Hz frame (order of operations in docs/duel.md):
+ *

content.content:
2072	+ *
2073	+ * 1. read both inputs (opposite directions cancel; newly pressed buttons enter the 4-frame buffer);
2074	+ * 2. detect every hit, block and grab of the frame against the start-of-frame state of both fighters;
2075	+ * 3. settle same-frame interactions (throw against throw breaks both; an active strike beats a throw);
2076	+ * 4. apply all results together, damage and stamina from start-of-frame values; fighters not struck advance their
2077	+ *    action or start a new one from their input;
2078	+ * 5. move, apply gravity, keep fighters inside the walls and apart;
2079	+ * 6. regenerate stamina, then decide KO, timeout and overtime from both fighters' health.
2080	+ *
2081	+ * Neither fighter is processed "first": every decision for one fighter reads only the start-of-frame state and the
2082	+ * frame's inputs. The input state is never mutated. A finished duel only advances its frame counter.
2083	+ */
2084	+export function stepDuel(config: DuelConfig, state: DuelState, inputs: DuelInputs): DuelState {
2085	+  const { moveset } = config;
2086	+  if (state.movesetVersion !== moveset.version) {
2087	+    throw new Error(`the duel runs on moveset ${state.movesetVersion}, not ${moveset.version}`);
2088	+  }
2089	+  const frame = state.frame + 1;
2090	+  if (state.result !== null) return { ...state, frame, events: [] };
2091	+
2092	+  const fighters = state.fighters;
2093	+  const input: Pair<FrameInput> = [readInput(moveset, fighters[0], inputs[0]), readInput(moveset, fighters[1], inputs[1])];
2094	+
2095	+  // 2. Detection, each against the same start-of-frame state.
2096	+  let contacts: Pair<Contact | null> = [detect(moveset, fighters, 0, input), detect(moveset, fighters, 1, input)];
2097	+
2098	+  // 3. Same-frame interactions.
2099	+  const clash = contacts[0]?.kind === "grab" && contacts[1]?.kind === "grab";
2100	+  if (clash) {
2101	+    contacts = [null, null];
2102	+  } else {
2103	+    contacts = [
2104	+      contacts[0]?.kind === "grab" && strikeActive(moveset, fighters[1]) ? null : contacts[0],
2105	+      contacts[1]?.kind === "grab" && strikeActive(moveset, fighters[0]) ? null : contacts[1],
2106	+    ];
2107	+  }
2108	+  const escape: Pair<boolean> = [escapes(fighters[0], input[0]), escapes(fighters[1], input[1])];
2109	+  const throwBreak = clash || escape[0] || escape[1];
2110	+
2111	+  // Displacement from pushback and throw breaks, from start-of-frame positions.
2112	+  const shift = [0, 0];
2113	+  const minX = moveset.fighter.pushbox.halfWidth;
2114	+  const maxX = moveset.arena.width - minX;
2115	+  for (const attacker of [0, 1] as const) {
2116	+    const contact = contacts[attacker];
2117	+    if (contact === null || contact.kind === "grab") continue;
2118	+    const defender = OTHER[attacker];
2119	+    const def = fighters[defender];
2120	+    const push = contact.kind === "hit" ? contact.move.hitPushback : contact.move.blockPushback;
2121	+    const direction = awayFrom(def, fighters[attacker]);
2122	+    const target = clampInt(def.x + direction * push, minX, maxX);
2123	+    shift[defender]! += target - def.x;
2124	+    // Against a wall, the rest of the pushback moves the attacker back instead.
2125	+    shift[attacker]! -= direction * (push - Math.abs(target - def.x));
2126	+  }
2127	+  if (throwBreak) {
2128	+    for (const index of [0, 1] as const) {
2129	+      shift[index]! += awayFrom(fighters[index], fighters[OTHER[index]]) * moveset.fighter.throwBreakPushback;
2130	+    }
2131	+  }
2132	+
2133	+  // 4. Apply results and advance actions.
2134	+  const events: DuelEvent[] = [];
2135	+  const spent = [false, false];
2136	+  const next = ([0, 1] as const).map((index): FighterState => {
2137	+    const self = fighters[index];
2138	+    const opponent = fighters[OTHER[index]];
2139	+    const incoming = contacts[OTHER[index]];
2140	+    const outgoing = contacts[index];
2141	+    const own = input[index];
2142	+    let fighter: FighterState = { ...self, held: own.bits, buffer: own.buffer };
2143	+    if (throwBreak) {
2144	+      // Two throws on one frame, or an escape: both fighters recover apart with no damage.
2145	+      if (clash) events.push({ kind: "throw-clash", attacker: index, moveId: self.moveId ?? "", damage: 0 });
2146	+      if (escape[OTHER[index]]) events.push({ kind: "throw-escape", attacker: index, moveId: moveset.commands.throw, damage: 0 });
2147	+      return startTimed(fighter, "throw-break", moveset.fighter.throwBreakFrames);
2148	+    }
2149	+    if (incoming !== null) {
2150	+      const attacker = OTHER[index];
2151	+      const result = react(moveset, fighter, incoming, attacker);
2152	+      events.push(result.event);
2153	+      if (incoming.kind === "block") spent[index] = true;
2154	+      return result.fighter;
2155	+    }
2156	+    if (outgoing !== null) fighter = { ...fighter, moveHit: true };
2157	+    if (fighter.action === "thrown") {
2158	+      if (fighter.timer > 0) return { ...fighter, timer: fighter.timer - 1, actionFrame: fighter.actionFrame + 1 };
2159	+      // The escape window ran out: the throw lands.
2160	+      const move = findMove(moveset, moveset.commands.throw);
2161	+      const damage = scaledDamage(moveset, move.damage, fighter.combo);
2162	+      events.push({ kind: "throw", attacker: OTHER[index], moveId: move.timing.id, damage });
2163	+      return {
2164	+        ...startTimed(fighter, "knockdown", move.hitstun),
2165	+        health: Math.max(0, fighter.health - damage),
2166	+        combo: fighter.combo + 1,
2167	+      };
2168	+    }
2169	+    if (!canAct(self)) return progress(moveset, fighter);
2170	+    const started = choose(moveset, fighter, opponent, own);
2171	+    if (started.action === "dash" || started.action === "backdash") spent[index] = true;
2172	+    return started;
2173	+  }) as unknown as Pair<FighterState>;
2174	+
2175	+  // 5. Movement: velocities, gravity and landing, walls, then pushboxes.
2176	+  const moved = ([0, 1] as const).map((index) => move(moveset, next[index], shift[index]!)) as unknown as Pair<FighterState>;
2177	+  const separated = separate(moveset, moved);
2178	+
2179	+  // 6. Stamina regeneration, then the result.
2180	+  const rules = moveset.rules;
2181	+  const final = ([0, 1] as const).map((index): FighterState => {
2182	+    const fighter = separated[index];
